"""Remove Duplicates from Sorted List — skip equal neighbours.

Time: O(n)   Space: O(1)
"""
if "ListNode" not in globals():
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next


class Solution:
    def deleteDuplicates(self, head):
        node = head
        while node and node.next:
            if node.val == node.next.val:
                node.next = node.next.next
            else:
                node = node.next
        return head
